grundstuecksrente_jahresabrechnung <- function(jahresrentenbetrag=NULL, rentenjahr_beginnt_am=NULL, berechtigungszeitraum_von=NULL, berechtigungszeitraum_bis=NULL, einordnungsnachweis=NULL) {
 rente <- .geld(jahresrentenbetrag);beginn <- .datum(rentenjahr_beginnt_am,'rentenjahr_beginnt_am');von <- .datum(berechtigungszeitraum_von,'berechtigungszeitraum_von');bis <- .datum(berechtigungszeitraum_bis,'berechtigungszeitraum_bis');.text(einordnungsnachweis,'einordnungsnachweis')
 if(bis<von) .fehler('berechtigungszeitraum_bis','Ende darf nicht vor Beginn liegen.')
 ende <- .frist(rentenjahr_beginnt_am,1,'jahre','tagesbeginn');tage <- as.integer(ende-beginn)+1;anteiltage <- max(0,as.integer(min(ende,bis)-max(beginn,von))+1)
 anteil <- .multiplizieren(rente,.bruch(anteiltage,tage))
 wert <- list(rentenjahr_endet_am=.iso(ende),regel_vorauszahlung_am=.iso(beginn),tage_im_rentenjahr=tage,zugeordnete_tage=anteiltage,jahresvorauszahlungsbetrag=.bruchteile(rente),zeitanteilig_zugeordneter_betrag=.bruchteile(anteil))
 eingaben <- list(jahresrentenbetrag=jahresrentenbetrag, rentenjahr_beginnt_am=rentenjahr_beginnt_am, berechtigungszeitraum_von=berechtigungszeitraum_von, berechtigungszeitraum_bis=berechtigungszeitraum_bis, einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .ergebnis(wert,"daten_tage_und_eur","BGB_GRUNDSTUECKSRENTE_JAHRESABRECHNUNG",eingaben,list(list(operation="Rentenjahr ab Tagesbeginn bestimmen; Schnittmenge mit Berechtigungszeitraum z\u00e4hlen und Jahresbetrag nach tats\u00e4chlichen Tagen zuordnen.")),eingaben)
 ergebnis$hinweise <- list("Gesetzlicher Jahresvorauszahlungsfall \u00a7\u00a7913II/917II; Jahresrentenh\u00f6he und Ausgangstag rechtlich bestimmt. \u00a7101Nr2 zeitanteilige Zuordnung regelm\u00e4\u00dfig wiederkehrender Ertr\u00e4ge bei begrenztem Bezugszeitraum; tats\u00e4chliche Kalendertage der Schnittmenge durch tats\u00e4chliche Tage des Rentenjahrs teilen. Kein pauschales365-Tage-Jahr und keine \u00dcbernahme der Sonderregel voller begonnener Leibrentenperioden aus\u00a7760. \u00a7915I Grundst\u00fcckswert ist historische Bewertung, kein von der Bibliothek gesch\u00e4tzter Preis; bis zur rechtlich bestimmten \u00dcbertragung bleibt die Rentenpflicht nachII ma\u00dfgeblich. Jahresvorauszahlungsbetrag und zugeordneter Zeitanteil getrennt: keine automatische R\u00fcckforderung bereits bezahlter Betr\u00e4ge oder doppelte zus\u00e4tzliche Forderung. Andere Eigent\u00fcmer getrennt mit \u00fcberschneidungsfreien Berechtigungszeiten abrechnen.")
 ergebnis
}
